// Simple Asteroid Salvage game targeting <canvas id="game"></canvas>
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = (canvas.width = canvas.clientWidth || 800);
  const H = (canvas.height = canvas.clientHeight || 600);

  // --- Game state -----------------------------------------------------------
  const ship = { x: W / 2, y: H - 50, w: 30, h: 30, speed: 4 };
  const keys = {};
  const asteroids = [];
  const debris = [];
  let fuel = 100; // percent
  let score = 0;
  let gameOver = false;

  // --- Helpers --------------------------------------------------------------
  const rectCollide = (a, b) =>
    a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;

  const spawnAsteroid = () => {
    const size = 20 + Math.random() * 30;
    asteroids.push({
      x: Math.random() * (W - size),
      y: -size,
      w: size,
      h: size,
      vy: 1 + Math.random() * 2,
    });
  };

  const spawnDebris = () => {
    const size = 10 + Math.random() * 10;
    debris.push({
      x: Math.random() * (W - size),
      y: -size,
      w: size,
      h: size,
      vy: 1 + Math.random() * 1.5,
    });
  };

  // --- Input ---------------------------------------------------------------
  window.addEventListener('keydown', (e) => (keys[e.key] = true));
  window.addEventListener('keyup', (e) => (keys[e.key] = false));

  // --- Main loop ------------------------------------------------------------
  const update = () => {
    if (gameOver) return;
    // move ship
    if (keys['ArrowLeft']) ship.x -= ship.speed;
    if (keys['ArrowRight']) ship.x += ship.speed;
    if (keys['ArrowUp']) ship.y -= ship.speed;
    if (keys['ArrowDown']) ship.y += ship.speed;
    // keep inside canvas
    ship.x = Math.max(0, Math.min(W - ship.w, ship.x));
    ship.y = Math.max(0, Math.min(H - ship.h, ship.y));

    // spawn entities
    if (Math.random() < 0.02) spawnAsteroid();
    if (Math.random() < 0.015) spawnDebris();

    // move asteroids
    asteroids.forEach((a) => (a.y += a.vy));
    debris.forEach((d) => (d.y += d.vy));

    // remove off‑screen
    const off = (obj) => obj.y > H;
    while (asteroids.length && off(asteroids[0])) asteroids.shift();
    while (debris.length && off(debris[0])) debris.shift();

    // collisions
    for (let i = asteroids.length - 1; i >= 0; i--) {
      if (rectCollide(ship, asteroids[i])) {
        gameOver = true;
        break;
      }
    }
    for (let i = debris.length - 1; i >= 0; i--) {
      if (rectCollide(ship, debris[i])) {
        score += 10;
        fuel = Math.min(100, fuel + 5);
        debris.splice(i, 1);
      }
    }

    // fuel consumption
    fuel -= 0.05;
    if (fuel <= 0) gameOver = true;
  };

  const draw = () => {
    ctx.clearRect(0, 0, W, H);
    // ship
    ctx.fillStyle = '#0af';
    ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
    // asteroids
    ctx.fillStyle = '#a33';
    asteroids.forEach((a) => ctx.fillRect(a.x, a.y, a.w, a.h));
    // debris
    ctx.fillStyle = '#3a3';
    debris.forEach((d) => ctx.fillRect(d.x, d.y, d.w, d.h));
    // HUD
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Fuel: ${fuel.toFixed(0)}%`, 10, 40);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', W / 2, H / 2);
    }
  };

  const loop = () => {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  };
  loop();
})();
